<?php
require '../config.php';require '../functions.php';require_admin();$id=(int)($_GET['id']??0);$p=['name'=>'','category'=>'Men','description'=>'','price'=>'','image'=>'','stock'=>10,'active'=>1];if($id){$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([$id]);$p=$s->fetch()?:$p;}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$data=[trim($_POST['name']??''),trim($_POST['category']??''),trim($_POST['description']??''),(float)($_POST['price']??0),trim($_POST['image']??''),(int)($_POST['stock']??0),isset($_POST['active'])?1:0];if(!$data[0]||!$data[1]||$data[3]<=0||!filter_var($data[4],FILTER_VALIDATE_URL))$error='Enter a name, category, positive price and valid image URL.';else{if($id){$data[]=$id;$s=$pdo->prepare("UPDATE products SET name=?,category=?,description=?,price=?,image=?,stock=?,active=? WHERE id=?");}else{$s=$pdo->prepare("INSERT INTO products(name,category,description,price,image,stock,active) VALUES(?,?,?,?,?,?,?)");}$s->execute($data);header('Location: index.php');exit;}}
$pageTitle='Product editor — Shopease';require '../header.php';?>
<section class="page-wrap narrow"><p class="eyebrow">ADMIN / PRODUCTS</p><h1 class="page-title"><?= $id?'Edit product':'Add product' ?></h1><?php if($error): ?><div class="error"><?= e($error) ?></div><?php endif; ?><form method="post" class="form-card"><label>Product name<input name="name" required value="<?= e($p['name']) ?>"></label><label>Category<input name="category" required value="<?= e($p['category']) ?>" placeholder="Men, Women, Tops, Accessories"></label><label>Description<textarea name="description" rows="4"><?= e($p['description']) ?></textarea></label><label>Price (INR)<input type="number" step="1" min="1" name="price" required value="<?= e($p['price']) ?>"></label><label>Image URL<input type="url" name="image" required value="<?= e($p['image']) ?>"></label><label>Stock<input type="number" min="0" name="stock" value="<?= e($p['stock']) ?>"></label><label class="check"><input type="checkbox" name="active" <?= $p['active']?'checked':'' ?>> Visible in store</label><button class="btn gold full">Save product</button></form></section><?php require '../footer.php'; ?>